GimCorpus.put(470,0,[[1,8,"בן תשעה חדשים וכו'. א\"א זה אינו מחוור שהרי הלכה כרשב\"ג דמשתהא:",1,0],[2,4,"כל קרובים שהוא חייב להתאבל עליהם וכו'. א\"א לא מחוור דבנו עצמו מדרבנן הוא:",1,0],[2,6,"בד\"א בזכרים שהוזהרו על הטומאה וכו'. א\"א קשיא לי הא דתניא אשתו ארוסה לא אונן ולא מיטמא לה וכן היא לא אוננת ולא מיטמאה לו הא נשואה מיטמאה לו:",1,0],[2,14,"אין הכהן מטמא לאבר מן החי מן אביו וכו' עד וכן שאר קרובים. א\"א הרב אינו פוסק כן:",1,0],[3,7,"נטמא מקודם וכו'. א\"א הרב אינו פוסק כן והא לא מיחוור דסוגיא דשמעתא כרבה דטומאה וטומאה שלא בחבורין נמי לא מחייב וכ\"ש בחבורין וטומאת ביאה נמי לא מיחייב אלא היכא דאתו בבת אחת:",1,0],[4,9,"וחייב לישב על מטה כפויה. א\"א לא ראיתי שורש לזה:",1,0],[6,1,"מדברי סופרים וכו' עד מצטער שלשים יום. א\"א בגמרא למצוה ראשיכם אל תפרעו ואתיא פרע פרע מנזיר עכ\"ל:",1,0],[6,7,"בד\"א בשאר מתים וכו' עד י\"ב חדש. א\"א ולשמחת מצוה עד שלשים יום כשאר מתים:",1,0],[10,3,"נמצא מונה לאחר ראש השנה ויום הכפורים שלשה ועשרים. א\"א יש כאן שבוש שהרי יום אחד לפני ראש השנה הרי הוא שבעה וראש השנה שבעה:",1,0],[11,7,"שבעת ימי החתנות וכו' עד ומונה השלשים מאחר שבעת ימי המשתה. א\"א ולמה לא יעלו ימי המשתה לשלשים:",1,0],[11,8,"הכין כל צרכי וכו'. א\"א זה אינו מחוור אלא לאחר שלשים:",1,0],[13,4,"מת שאין לו וכו' עד מתקבצין עשרה משאר העם ויושבין במקומו. א\"א זה אין לו שורש:",1,0]]);
